import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteEssenceHandler } from "../handlers/deleteEssenceHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof deleteEssenceHandler>>;
type Vars = string;

export function useDeleteEssence(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteEssenceHandler(vars),
    ...options,
  });
}
